schema.code:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://faion.net/schemas/incident-decision-template.json",
  "title": "Incident decision record",
  "type": "object",
  "required": ["trigger", "owner", "inputs", "decision", "evidence", "review"],
  "additionalProperties": false,
  "definitions": {
    "handle": {"type": "string", "pattern": "^[a-z-]+:[a-z0-9._-]+$"},
    "timestamp": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2})?(Z|[+-][0-9]{2}:[0-9]{2})$"},
    "date": {"type": "string", "pattern": "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"}
  },
  "properties": {
    "__faion_header__": {"type": "object"},
    "trigger": {
      "type": "object",
      "required": ["kind", "url", "incident_id", "decided_at", "committed_at", "bridge_open_at_commit"],
      "additionalProperties": false,
      "properties": {
        "kind": {"type": "string", "const": "incident"},
        "url": {"type": "string", "pattern": "^https://"},
        "incident_id": {"type": "string", "minLength": 3},
        "decided_at": {"$ref": "#/definitions/timestamp"},
        "committed_at": {"$ref": "#/definitions/timestamp"},
        "bridge_open_at_commit": {"type": "boolean"}
      }
    },
    "owner": {"$ref": "#/definitions/handle"},
    "inputs": {
      "type": "array",
      "minItems": 3,
      "allOf": [
        {"contains": {"properties": {"name": {"const": "options_considered"}}}},
        {"contains": {"properties": {"name": {"const": "blast_radius"}}}},
        {"contains": {"properties": {"name": {"const": "rollback_trigger"}}}}
      ],
      "items": {
        "type": "object",
        "required": ["name", "value"],
        "additionalProperties": false,
        "properties": {
          "name": {"type": "string", "enum": ["options_considered", "blast_radius", "rollback_trigger", "executor", "reconstructed"]},
          "value": {}
        },
        "allOf": [
          {"if": {"properties": {"name": {"const": "options_considered"}}},
           "then": {"properties": {"value": {
             "type": "array", "minItems": 2,
             "items": {"type": "string", "minLength": 12},
             "contains": {"type": "string", "pattern": "[Dd]o nothing|[Kk]eep observing"}}}}},
          {"if": {"properties": {"name": {"const": "blast_radius"}}},
           "then": {"properties": {"value": {"type": "string", "minLength": 10, "pattern": "[0-9]"}}}},
          {"if": {"properties": {"name": {"const": "rollback_trigger"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["metric", "threshold", "window", "rollback"],
             "additionalProperties": false,
             "properties": {
               "metric": {"type": "string", "minLength": 3},
               "threshold": {"type": "string", "minLength": 2, "pattern": "[0-9]"},
               "window": {"type": "string", "minLength": 2, "pattern": "[0-9]"},
               "rollback": {"type": "string", "minLength": 4}}}}}},
          {"if": {"properties": {"name": {"const": "executor"}}},
           "then": {"properties": {"value": {"$ref": "#/definitions/handle"}}}},
          {"if": {"properties": {"name": {"const": "reconstructed"}}},
           "then": {"properties": {"value": {
             "type": "object",
             "required": ["reconstructed", "at"],
             "additionalProperties": false,
             "properties": {"reconstructed": {"const": true}, "at": {"$ref": "#/definitions/timestamp"}}}}}}
        ]
      }
    },
    "decision": {
      "type": "string",
      "minLength": 12,
      "pattern": "^(?![\\s\\S]*([Cc]onsider|[Mm]aybe|[Ll]ook into|[Ss]hould probably))[^.!?]+[.!]?$"
    },
    "evidence": {
      "type": "array",
      "minItems": 1,
      "items": {"type": "string", "pattern": "^https://"}
    },
    "review": {
      "type": "object",
      "required": ["postmortem_date", "next_review_at"],
      "additionalProperties": false,
      "properties": {
        "postmortem_date": {"$ref": "#/definitions/date"},
        "next_review_at": {"$ref": "#/definitions/date"},
        "outcome": {
          "type": "object",
          "required": ["rollback_trigger_fired", "blast_radius_matched", "reviewed_at"],
          "additionalProperties": false,
          "properties": {
            "rollback_trigger_fired": {"type": "boolean"},
            "blast_radius_matched": {"type": "boolean"},
            "measured_blast_radius": {"type": "string"},
            "reviewed_at": {"$ref": "#/definitions/date"}
          }
        }
      }
    }
  }
}

output-contract.example:
{
  "trigger": {
    "kind": "incident",
    "url": "https://acme.pagerduty.com/incidents/Q2X4",
    "incident_id": "INC-2417",
    "decided_at": "2026-09-12T02:14:00Z",
    "committed_at": "2026-09-12T02:15:40Z",
    "bridge_open_at_commit": true
  },
  "owner": "ic:alice",
  "inputs": [
    {"name": "options_considered", "value": [
      "disable the recommendations sidecar in eu-west-1 (chosen: isolates the failing dependency, 1 min to apply)",
      "roll back the full checkout release 41 -> 40 (rejected: 20 min, widens blast radius to all regions)",
      "do nothing / keep observing for 10 min (rejected: 5xx rate rising 0.4 pp per minute)"
    ]},
    {"name": "blast_radius", "value": "38% of checkout requests in eu-west-1 returning 5xx, approx. 1,900 req/min, 3 tenants on dedicated shards unaffected"},
    {"name": "rollback_trigger", "value": {
      "metric": "checkout_http_5xx_rate (grafana: checkout-overview)",
      "threshold": "above 2%",
      "window": "5 consecutive minutes",
      "rollback": "helm rollback checkout 41 -n prod-eu-west-1"
    }},
    {"name": "executor", "value": "sre:bob"}
  ],
  "decision": "Disable the recommendations sidecar in eu-west-1 now.",
  "evidence": [
    "https://grafana.acme.internal/d/checkout-overview?from=1789178400000&to=1789180200000&var-region=eu-west-1",
    "https://acme.pagerduty.com/incidents/Q2X4/alerts/A7",
    "https://acme.slack.com/archives/C0INC2417/p1789178040001200"
  ],
  "review": {
    "postmortem_date": "2026-09-15",
    "next_review_at": "2026-09-15",
    "outcome": {
      "rollback_trigger_fired": false,
      "blast_radius_matched": true,
      "measured_blast_radius": "36% of eu-west-1 checkout requests over 11 minutes",
      "reviewed_at": "2026-09-15"
    }
  }
}

{
  "trigger": {
    "kind": "incident",
    "url": "https://acme.pagerduty.com/incidents/Q2X4",
    "incident_id": "INC-2417",
    "decided_at": "2026-09-12T02:14:00Z",
    "committed_at": "2026-09-12T02:15:40Z",
    "bridge_open_at_commit": true
  },
  "owner": "sre:bob",
  "inputs": [
    {"name": "options_considered", "value": [
      "disable the recommendations sidecar in eu-west-1 (chosen)"
    ]},
    {"name": "blast_radius", "value": "some EU users seeing errors on checkout"},
    {"name": "rollback_trigger", "value": {
      "metric": "checkout errors",
      "threshold": "if it gets worse",
      "window": "a while",
      "rollback": "roll back"
    }},
    {"name": "executor", "value": "sre:bob"}
  ],
  "decision": "We should probably consider disabling the sidecar and look into the release.",
  "evidence": [
    "https://grafana.acme.internal/d/checkout-overview",
    "https://docs.acme.internal/runbooks/checkout"
  ],
  "review": {
    "postmortem_date": "2026-09-15",
    "next_review_at": "2026-12-15"
  }
}
